description:
Write a binary format for a game's save file with `record Save(String player, int level, List<Integer> scores)` and a class `SaveFormat`:

- `static byte[] write(Save save)`: the bytes, in this order (all numbers big-endian, as `DataOutputStream` writes them):
  1. the magic bytes `'X' 'S' 'A' 'V'`;
  2. the version, an `int` 1;
  3. the player name with `writeUTF`;
  4. the level, an `int`;
  5. the number of scores, an `int`, then each score as an `int`;
  6. a CRC-32 (`java.util.zip.CRC32`) of **everything before it**, as a `long`.
- `static Save read(byte[] data)`: the reverse. It throws `IOException` with a clear message when the magic bytes are wrong (`"not a save file"`), the version is not 1 (`"unsupported version 2"`), the checksum does not match (`"damaged file"`), or the data ends too early.

starter.SaveFormat.java:
import java.io.IOException;

public class SaveFormat {
    public static byte[] write(Save save) throws IOException { return new byte[0]; }
    public static Save read(byte[] data) throws IOException { return null; }
}

solution.SaveFormat.java:
import java.io.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.zip.CRC32;

public class SaveFormat {
    private static final byte[] MAGIC = { 'X', 'S', 'A', 'V' };

    public static byte[] write(Save save) throws IOException {
        var buffer = new ByteArrayOutputStream();
        try (var out = new DataOutputStream(buffer)) {
            out.write(MAGIC);
            out.writeInt(1);
            out.writeUTF(save.player());
            out.writeInt(save.level());
            out.writeInt(save.scores().size());
            for (int s : save.scores()) out.writeInt(s);
        }
        byte[] body = buffer.toByteArray();
        var crc = new CRC32();
        crc.update(body);
        var full = new ByteArrayOutputStream();
        try (var out = new DataOutputStream(full)) {
            out.write(body);
            out.writeLong(crc.getValue());
        }
        return full.toByteArray();
    }

    public static Save read(byte[] data) throws IOException {
        if (data.length < 8) throw new EOFException("the file is too short");
        byte[] body = Arrays.copyOf(data, data.length - 8);
        try (var in = new DataInputStream(new ByteArrayInputStream(data))) {
            byte[] magic = new byte[4];
            in.readFully(magic);
            if (!Arrays.equals(magic, MAGIC)) throw new IOException("not a save file");
            int version = in.readInt();
            if (version != 1) throw new IOException("unsupported version " + version);
            var crc = new CRC32();
            crc.update(body);
            long stored = new DataInputStream(new ByteArrayInputStream(data, data.length - 8, 8)).readLong();
            if (stored != crc.getValue()) throw new IOException("damaged file");
            String player = in.readUTF();
            int level = in.readInt();
            int count = in.readInt();
            List<Integer> scores = new ArrayList<>();
            for (int i = 0; i < count; i++) scores.add(in.readInt());
            return new Save(player, level, scores);
        }
    }
}

unitTests:
var save = new Save("Ada", 7, List.of(120, 340, 95));

test("round trip", () -> {
    byte[] bytes = SaveFormat.write(save);
    checkEq(new String(bytes, 0, 4, java.nio.charset.StandardCharsets.US_ASCII), "XSAV");
    checkEq(bytes.length, 4 + 4 + (2 + 3) + 4 + 4 + 3 * 4 + 8);
    checkEq(SaveFormat.read(bytes), save);
    checkEq(SaveFormat.read(SaveFormat.write(new Save("", 0, List.of()))), new Save("", 0, List.of()));
});

test("bad files are refused", () -> {
    byte[] good = SaveFormat.write(save);
    String[] messages = new String[3];

    byte[] wrongMagic = good.clone(); wrongMagic[0] = 'Y';
    byte[] newVersion = good.clone(); newVersion[7] = 2;
    byte[] damaged = good.clone(); damaged[12] ^= 1;
    byte[][] cases = { wrongMagic, newVersion, damaged };
    for (int i = 0; i < 3; i++) {
        try { SaveFormat.read(cases[i]); } catch (IOException e) { messages[i] = e.getMessage(); }
    }
    checkEq(messages[0], "not a save file");
    checkEq(messages[1], "unsupported version 2");
    checkEq(messages[2], "damaged file");
    checkThrows(IOException.class, () -> SaveFormat.read(java.util.Arrays.copyOf(good, 10)));
});

